// ============================================================
// PARSE + COOLDOWN — Evolution API (v2)
// Extrai o número REAL do remetente e aplica cooldown de 6h:
// depois de saudar um cliente, o bot silencia (não atrapalha
// atendimento humano). Se o DONO responder, renova o cooldown.
// ============================================================
const body = $input.first().json.body || $input.first().json;
const event = body.event || '';
const data = body.data || {};
const key = data.key || {};

// Eventos que não são mensagem: ignorar
if (event && !/messages\.upsert|MESSAGES_UPSERT/i.test(event)) return [];

// Ignorar grupos
if ((key.remoteJid || '').includes('@g.us')) return [];

// Número REAL do remetente (quando remoteJid é @lid, o real vem em outros campos)
const candidatos = [key.senderPn, key.participantPn, key.remoteJidAlt, key.participant, data.sender, data.senderPn, data.remoteJidAlt, key.remoteJid].filter(Boolean);
let numero = null;
for (const cand of candidatos) {
  if (typeof cand !== 'string') continue;
  if (cand.includes('@g.us') || cand.endsWith('@lid')) continue;
  const n = cand.split('@')[0];
  if (/^\d{8,15}$/.test(n)) { numero = n; break; }
}
if (!numero) return [];

// Cooldown persistido entre execuções
const COOLDOWN_MS = 6 * 60 * 60 * 1000;
const __sd = $getWorkflowStaticData('global');
const cd = __sd.cooldown || {};
// limpeza de entradas velhas
for (const [k, ts] of Object.entries(cd)) { if (Date.now() - ts > COOLDOWN_MS) delete cd[k]; }

// Dono respondeu manualmente → renova cooldown e silencia
if (key.fromMe) {
  cd[numero] = Date.now();
  __sd.cooldown = cd;
  return [];
}

// Cliente em cooldown → silencia
if (cd[numero] && Date.now() - cd[numero] < COOLDOWN_MS) return [];

__sd.cooldown = cd;
return [{ json: { numero } }];

// ============================================================
// MONTA A MENSAGEM — tudo vem das CONFIGURAÇÕES da plataforma
// Prioridade: 1) alerta ativo  2) fechado  3) saudação padrão
// ============================================================
const cfg = $input.first().json;
const { numero } = $('Parse + Cooldown').first().json;

const nome = cfg.nome_estabelecimento || 'nosso estabelecimento';
const link = (cfg.link_exibicao || '').trim();
const alerta = (cfg.mensagem_alerta || '').trim();
const aberto = !!cfg.aberto;
const h = cfg.horario || {};

const blocoLink = link ? `\n\nAcesse nosso cardápio e faça seu pedido pelo link abaixo:\n🌐 *${link}*` : '';

let texto;
if (alerta) {
  // Adversidade (ex.: chapa queimou) — saudação + alerta + compreensão
  texto = `Olá! 👋 Aqui é da *${nome}*.\n\n⚠️ *Aviso importante:*\n${alerta}\n\nPedimos desculpas pelo transtorno e agradecemos a sua compreensão. 🙏${blocoLink}`;
} else if (!aberto) {
  const DIAS = ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
  const dias = (h.dias || []).map(d => DIAS[d]);
  const diasStr = dias.length === 7 ? 'Todos os dias' : dias.join(', ');
  texto = `🔒 *Olá! No momento a ${nome} está fechada.*\n\nNosso horário de funcionamento:\n📅 *${diasStr}*\n🕐 *${h.abertura || ''} às ${h.fechamento || ''}*${blocoLink}\n\n_Te esperamos em breve!_ 😊`;
} else {
  texto = `Olá! 👋 Seja bem-vindo(a) à *${nome}*! 🍔${blocoLink}\n\n_Após finalizar o pedido, você receberá as atualizações aqui pelo WhatsApp!_ 📲`;
}

// Marca cooldown AGORA (envio vem em seguida)
const __sd = $getWorkflowStaticData('global');
const cd = __sd.cooldown || {};
cd[numero] = Date.now();
__sd.cooldown = cd;

return [{ json: { numero, texto } }];
